steps.run:
if ($env:RUNNER_NAME -ne $env:EXPECTED_RUNNER_NAME) {
  throw "Expected $env:EXPECTED_RUNNER_NAME but routed to $env:RUNNER_NAME"
}
$drive = (Get-Item $env:GITHUB_WORKSPACE).PSDrive.Name
$disk = [math]::Round((Get-PSDrive $drive).Free / 1GB, 1)
$memory = [math]::Round((Get-CimInstance Win32_OperatingSystem).FreePhysicalMemory / 1MB, 1)
$line = @{ runner = $env:RUNNER_NAME; os = 'Windows'; disk_free_gb = $disk; mem_available_gb = $memory } | ConvertTo-Json -Compress
Write-Output "COMPUTE_PANEL_PROBE $line"
python -I -B scripts/ci/self-hosted/resource-maintenance/probe.py
if ($LASTEXITCODE -ne 0) { throw "Maintenance probe failed" }

